import {
  ArrowDown,
  ArrowLeft,
  ArrowRight,
  ArrowUp,
  SlidersHorizontal,
} from "lucide-react";
import React, { useState } from "react";

type MobileKeyDockProps = {
  onSendKey: (key: string) => void;
};

export const MobileKeyDock: React.FC<MobileKeyDockProps> = ({ onSendKey }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [ctrlLatched, setCtrlLatched] = useState(false);
  const [altLatched, setAltLatched] = useState(false);

  const triggerKey = (action: string) => {
    // Haptic vibration if supported
    if ("vibrate" in navigator) {
      try {
        navigator.vibrate(15);
      } catch {
        // ignore
      }
    }

    if (action === "ctrl") {
      setCtrlLatched(!ctrlLatched);
      return;
    }
    if (action === "alt") {
      setAltLatched(!altLatched);
      return;
    }

    let finalAction = action;
    if (ctrlLatched) {
      finalAction = `ctrl-${action}`;
      setCtrlLatched(false);
    } else if (altLatched) {
      finalAction = `alt-${action}`;
      setAltLatched(false);
    }

    onSendKey(finalAction);
  };

  return (
    <div className="w-full bg-card border-t border-border select-none touch-manipulation z-30">
      {/* Expanded utility row */}
      {isExpanded && (
        <div className="flex gap-1.5 px-2 pt-2 pb-1 overflow-x-auto no-scrollbar text-xs font-mono">
          <KeyButton label="~" onClick={() => triggerKey("~")} />
          <KeyButton label="`" onClick={() => triggerKey("`")} />
          <KeyButton label="|" onClick={() => triggerKey("|")} />
          <KeyButton label="/" onClick={() => triggerKey("/")} />
          <KeyButton label="\" onClick={() => triggerKey("\\")} />
          <KeyButton label="-" onClick={() => triggerKey("-")} />
          <KeyButton label="_" onClick={() => triggerKey("_")} />
          <KeyButton label="=" onClick={() => triggerKey("=")} />
          <KeyButton label="PgUp" onClick={() => triggerKey("pageup")} />
          <KeyButton label="PgDn" onClick={() => triggerKey("pagedown")} />
          <KeyButton label="Home" onClick={() => triggerKey("home")} />
          <KeyButton label="End" onClick={() => triggerKey("end")} />
          <KeyButton label="Ctrl-Z" onClick={() => triggerKey("ctrl-z")} />
          <KeyButton label="Ctrl-D" onClick={() => triggerKey("ctrl-d")} />
        </div>
      )}

      {/* Primary essential row */}
      <div className="flex items-center justify-between gap-1 px-2 py-1.5 overflow-x-auto no-scrollbar">
        <div className="flex items-center gap-1.5">
          <KeyButton
            label="Ctrl"
            active={ctrlLatched}
            onClick={() => triggerKey("ctrl")}
            className="font-semibold"
          />
          <KeyButton
            label="Alt"
            active={altLatched}
            onClick={() => triggerKey("alt")}
            className="font-semibold"
          />
          <KeyButton label="Esc" onClick={() => triggerKey("esc")} />
          <KeyButton label="Tab" onClick={() => triggerKey("tab")} />
          <KeyButton
            label="Ctrl-C"
            highlight
            onClick={() => triggerKey("ctrl-c")}
            className="font-bold text-destructive-foreground border-destructive/50 bg-destructive/20"
          />
        </div>

        <div className="flex items-center gap-1">
          <KeyButton icon={<ArrowLeft size={14} />} onClick={() => triggerKey("left")} />
          <KeyButton icon={<ArrowUp size={14} />} onClick={() => triggerKey("up")} />
          <KeyButton icon={<ArrowDown size={14} />} onClick={() => triggerKey("down")} />
          <KeyButton icon={<ArrowRight size={14} />} onClick={() => triggerKey("right")} />
          <KeyButton
            icon={<SlidersHorizontal size={13} />}
            active={isExpanded}
            onClick={() => setIsExpanded(!isExpanded)}
            title="More keys"
          />
        </div>
      </div>
    </div>
  );
};

function KeyButton({
  label,
  icon,
  active,
  highlight,
  onClick,
  className = "",
  title,
}: {
  label?: string;
  icon?: React.ReactNode;
  active?: boolean;
  highlight?: boolean;
  onClick: () => void;
  className?: string;
  title?: string;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      title={title}
      className={`min-w-[38px] h-8 px-2 flex items-center justify-center rounded border text-xs font-mono font-medium transition-all active:scale-95 ${
        active
          ? "bg-primary border-primary text-primary-foreground shadow-sm"
          : highlight
          ? "border-border text-foreground bg-secondary hover:bg-secondary/80"
          : "bg-secondary/60 border-border text-foreground hover:bg-secondary hover:text-foreground"
      } ${className}`}
    >
      {icon || label}
    </button>
  );
}

import { LoaderCircle } from "lucide-react";

import { cn } from "../../lib/cn";
import type { TerminalActivityState } from "../../lib/activity";
import type { AgentState } from "../../lib/types";

export type StatusDotState = AgentState | TerminalActivityState | "unread";

type StatusDotProps = {
  state: StatusDotState;
  className?: string;
};

export function StatusDot({ state, className }: StatusDotProps) {
  if (state === "working") {
    return (
      <LoaderCircle
        aria-hidden="true"
        data-status-state="working"
        className={cn("size-3 shrink-0 animate-spin text-status-working motion-reduce:animate-none", className)}
      />
    );
  }

  if (state === "starting") {
    return (
      <span
        aria-hidden="true"
        data-status-state="starting"
        className={cn("size-2 shrink-0 animate-pulse rounded-full bg-status-warning motion-reduce:animate-none", className)}
      />
    );
  }

  if (state === "waiting") {
    return (
      <span
        aria-hidden="true"
        data-status-state="waiting"
        className={cn("size-2 shrink-0 rounded-full bg-status-warning ring-2 ring-status-warning/20", className)}
      />
    );
  }

  if (state === "unread") {
    return (
      <span
        aria-hidden="true"
        data-status-state="unread"
        className={cn("size-2 shrink-0 rounded-full bg-primary", className)}
      />
    );
  }

  if (state === "done" || state === "exited") {
    return (
      <span
        aria-hidden="true"
        data-status-state="done"
        className={cn("size-2 shrink-0 rounded-full bg-status-success", className)}
      />
    );
  }

  return (
    <span
      aria-hidden="true"
      data-status-state="failed"
      className={cn("size-2 shrink-0 rounded-full bg-destructive", className)}
    />
  );
}

import { useEffect, useRef, useState } from "react";

import { terminalHostManager } from "../lib/terminalHostManager";
import { fitTerminal } from "../lib/terminalInstanceFactory";
import { useTerminalSettings } from "../lib/terminalSettings";
import type { TerminalSession } from "../lib/types";
import { TerminalSearchOverlay } from "./TerminalSearchOverlay";

type TerminalPaneProps = {
  session: TerminalSession;
  active: boolean;
  onBell?: () => void;
  onTitleChange?: (title: string) => void;
  searchOpen?: boolean;
  onCloseSearch?: () => void;
};

export function TerminalPane({ session, active, onBell, onTitleChange, searchOpen, onCloseSearch }: TerminalPaneProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [error, setError] = useState<string | null>(null);
  const { settings } = useTerminalSettings();

  useEffect(() => {
    return terminalHostManager.registerVisible(session.id);
  }, [session.id]);

  useEffect(() => {
    terminalHostManager.applyInstanceSettings(session.id, settings);
  }, [session.id, settings]);

  useEffect(() => {
    terminalHostManager.updateSession(session.id, session);
  }, [session]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    let cancelled = false;

    void terminalHostManager
      .getOrCreate(session, active, onBell, onTitleChange)
      .then((instance) => {
        if (cancelled) return;
        if (!container.contains(instance.element)) {
          container.replaceChildren(instance.element);
        }
        if (active) {
          instance.terminal.focus();
        }

        const fontsReady = typeof document !== "undefined" ? document.fonts?.ready : undefined;
        void fontsReady?.then(() => {
          if (!cancelled && instance.element.clientWidth > 0 && instance.element.clientHeight > 0) {
            fitTerminal(instance.terminal, instance.fitAddon);
          }
        });
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err instanceof Error ? err.message : "Failed to mount terminal");
      });

    return () => {
      cancelled = true;
    };
  }, [session.id]);

  useEffect(() => {
    const instance = terminalHostManager.getInstance(session.id);
    if (instance) {
      instance.active = active;
      if (active) {
        instance.terminal.focus();
      }
    }
  }, [active, session.id]);

  return (
    <div
      data-testid="terminal-pane-surface"
      className="relative h-full w-full min-h-0 min-w-0 overflow-hidden"
      style={{ backgroundColor: settings.theme.background }}
    >
      <div
        ref={containerRef}
        data-testid="terminal-mount"
        className="relative h-full w-full min-h-0 min-w-0 overflow-hidden"
        style={{ backgroundColor: settings.theme.background }}
      />
      {searchOpen ? (
        <TerminalSearchOverlay
          instance={terminalHostManager.getInstance(session.id)}
          onClose={onCloseSearch ?? (() => undefined)}
        />
      ) : null}
      {error ? (
        <div className="pointer-events-none absolute bottom-3 right-3 max-w-error rounded-md border border-destructive/30 bg-destructive/10 px-2 py-1 text-[11px] text-destructive">
          {error}
        </div>
      ) : null}
    </div>
  );
}

