import path from 'node:path';
import { createRequire } from 'node:module';

const require = createRequire('/Users/indo/code/project/orca-lite/ui/package.json');
const { WebSocketServer } = require('ws');

const root = '/tmp/ferryx-remote-qa-st_01a02c9b/dist';
const logPath = '/tmp/ferryx-remote-qa-st_01a02c9b/fixture-requests.log';
let mode = 'active';

const activeState = {
  activeWorkspaceId: 'safe-ui',
  activeWorktreeSlug: 'main',
  activeWorktreeLabel: 'main',
  activeSessionId: 'session-active',
  projects: [
    { workspaceId: 'safe-ui', worktrees: [{ slug: 'main', label: 'main', path: 'ACTIVE_PATH_SENTINEL' }] },
    { workspaceId: 'safe-api', worktrees: [{ slug: 'feature-safe', label: 'feature-safe', path: 'BACKGROUND_PATH_SENTINEL' }] },
  ],
  sessions: [
    { sessionId: 'session-active', title: 'ACTIVE_TERMINAL_TITLE', workspaceId: 'safe-ui', worktreeLabel: 'main', running: true },
    { sessionId: 'session-background', title: 'BACKGROUND_TERMINAL_TITLE', workspaceId: 'safe-api', worktreeLabel: 'feature-safe', path: 'BACKGROUND_PATH_SENTINEL', running: true },
  ],
};

const confirmedState = {
  activeContext: {
    workspaceId: 'safe-api',
    worktreeSlug: 'feature-safe',
    worktreeLabel: 'feature-safe',
    activeTerminal: null,
  },
  projects: activeState.projects,
  sessions: activeState.sessions,
};

const noFocusState = {
  activeContext: {
    workspaceId: 'safe-ui',
    worktreeSlug: 'main',
    worktreeLabel: 'main',
    activeTerminal: null,
  },
  projects: activeState.projects,
  sessions: [activeState.sessions[1]],
};

function log(message) {
  fs.appendFileSync(logPath, `${new Date().toISOString()} ${message}\n`);
}

function json(res, body, status = 200) {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'content-length': Buffer.byteLength(payload),
    'cache-control': 'no-store',
  });
  res.end(payload);
}

const mime = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.ico': 'image/x-icon',
  '.svg': 'image/svg+xml',
  '.woff2': 'font/woff2',
  '.webmanifest': 'application/manifest+json',
};

const server = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://127.0.0.1');
  log(`${req.method} ${url.pathname}`);

  if (req.method === 'GET' && url.pathname === '/api/v1/workspace/state') {
    json(res, mode === 'active' ? activeState : mode === 'confirmed' ? confirmedState : noFocusState);
    return;
  }

  if (req.method === 'POST' && url.pathname === '/api/v1/workspace/select') {
    let body = '';
    req.on('data', (chunk) => { body += chunk; });
    req.on('end', () => {
      log(`SELECT_BODY ${body}`);
      setTimeout(() => {
        mode = 'confirmed';
        json(res, { accepted: true });
      }, 6000);
    });
    return;
  }

  if (req.method === 'POST' && url.pathname === '/__qa/mode/no-focus') {
    mode = 'no-focus';
    json(res, { mode });
    return;
  }

  if (url.pathname.startsWith('/api/')) {
    json(res, { error: 'not found' }, 404);
    return;
  }

  let filePath = path.join(root, decodeURIComponent(url.pathname));
  if (url.pathname === '/' || !path.extname(filePath)) filePath = path.join(root, 'index.html');
  if (!filePath.startsWith(root)) {
    res.writeHead(403).end('forbidden');
    return;
  }
  fs.readFile(filePath, (error, data) => {
    if (error) {
      res.writeHead(404).end('not found');
      return;
    }
    res.writeHead(200, {
      'content-type': mime[path.extname(filePath)] ?? 'application/octet-stream',
      'cache-control': 'no-store',
    });
    res.end(data);
  });
});

const wss = new WebSocketServer({ noServer: true });
server.on('upgrade', (req, socket, head) => {
  const url = new URL(req.url, 'http://127.0.0.1');
  const match = url.pathname.match(/^\/api\/v1\/terminal\/([^/]+)$/);
  if (!match) {
    socket.destroy();
    return;
  }
  const sessionId = decodeURIComponent(match[1]);
  log(`WS_UPGRADE ${sessionId}`);
  if (sessionId !== 'session-active') {
    log(`UNEXPECTED_WS_SESSION ${sessionId}`);
    socket.destroy();
    return;
  }
  wss.handleUpgrade(req, socket, head, (ws) => {
    wss.emit('connection', ws, req);
    ws.send('\u001b[1;32mACTIVE_TERMINAL_TITLE\u001b[0m\r\nfocused session only\r\n');
    ws.on('message', (message) => log(`WS_CLIENT ${message.length} bytes`));
  });
});

server.listen(0, '127.0.0.1', () => {
  const address = server.address();
  fs.writeFileSync('/tmp/ferryx-remote-qa-st_01a02c9b/server.json', JSON.stringify({ pid: process.pid, port: address.port }));
  log(`LISTEN pid=${process.pid} port=${address.port}`);
  console.log(JSON.stringify({ pid: process.pid, port: address.port }));
});

function shutdown(signal) {
  log(`SHUTDOWN ${signal}`);
  for (const client of wss.clients) client.close();
  server.close(() => process.exit(0));
  setTimeout(() => process.exit(1), 2000).unref();
}
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

